296	    ///
297	    /// Returns [`RegistryError::UpstreamUnavailable`] without hitting the
298	    /// network when the circuit breaker is open.
299	    pub async fn fetch_tarball_response(
300	        &self,
301	        name: &PackageName,
302	        filename: &str,
303	    ) -> Result<FetchOutcome<reqwest::Response>> {
304	        self.ensure_available()?;
305	        let url = format!("{}/{}/-/{}", self.base.trim_end_matches('/'), name.as_str(), filename);
306	        let client = self.client.acquire_for_url(&url).await;
307	        let request = client.get(&url).timeout(self.timeout).headers(self.headers.clone());
308	        let response = self.run(request, &url).await?;
309	        if response.status() == StatusCode::NOT_FOUND {
310	            self.breaker.record_success();
311	            return Ok(FetchOutcome::NotFound);
312	        }
313	        let response = self.checked(response, &url).await?;
314	        // Success here covers only headers; a mid-stream body failure is
315	        // the caller's to observe. Recording success on a clean status is
316	        // what verdaccio does too.
317	        self.breaker.record_success();
