332	    /// [`RegistryError::Upstream`] and counting it against the breaker.
333	    async fn run(&self, request: reqwest::RequestBuilder, url: &str) -> Result<reqwest::Response> {
334	        request.send().await.map_err(|source| {
335	            self.breaker.record_failure();
336	            RegistryError::Upstream { url: url.to_string(), source }
