340	    /// Pass a successful response through; map any non-success status to
341	    /// [`RegistryError::UpstreamStatus`]. Only a `5xx` counts against the
342	    /// breaker — a non-404 `4xx` is an authoritative client error (auth,
343	    /// rate-limit, bad request), not an availability signal, so it leaves
344	    /// the breaker untouched rather than opening the circuit and masking
345	    /// the real status behind a `503`. The `404`/`304` paths are handled
346	    /// by the callers before reaching here.
347	    async fn checked(&self, response: reqwest::Response, url: &str) -> Result<reqwest::Response> {
