    /// Validate that `filename` is a plausible tarball name for this
    /// package and return `(canonical_filename, version)`.
    ///
    /// The canonical filename is always the short disk-and-URL form
    /// (`<basename>-<version>.tgz`, e.g. `node-20.0.0.tgz` for
    /// `@types/node`). Three input shapes are accepted:
    ///
    /// * `<basename>-<version>.tgz` — the canonical form verdaccio uses
    ///   and what client GETs send (`/foo/-/foo-1.0.0.tgz`).
    /// * `<full-name>-<version>.tgz` — the form `libnpmpublish` puts in
    ///   the `_attachments` key of a publish body for scoped packages
    ///   (`@scope/name-1.0.0.tgz`). For unscoped packages this collapses
    ///   to the first form.
    /// * the URL-encoded full-name form (`@scope%2Fname-1.0.0.tgz`,
    ///   sometimes with `@` as `%40`) a client may send in a tarball GET.
    ///
    /// Rejects filenames for other packages, path-traversal prefixes,
    /// and filenames missing the `.tgz` extension. The version segment
    /// is returned so the publish handler can look up `versions[v].dist`
    /// and the tarball screen can consult the OSV database.
    pub fn parse_tarball_name(&self, filename: &str) -> Result<(String, String), RegistryError> {
        let version = self
            .extract_version(filename)
            // A scoped full-name tarball URL arrives with its `@scope/name`
            // separator percent-encoded; decode and retry so the literal
            // package name still matches.
            .or_else(|| {
                filename
                    .contains('%')
                    .then(|| percent_decode(filename))
                    .flatten()
                    .and_then(|decoded| self.extract_version(&decoded))
            })
            .ok_or_else(|| RegistryError::InvalidTarballName {
                package: self.raw.clone(),
                filename: filename.to_string(),
            })?;
        Ok((format!("{}-{}.tgz", self.basename, version), version))
    }

    /// Extract the version segment from a tarball `filename` whose
    /// package part is already in a literal (decoded) form, or `None`
    /// when it isn't a valid tarball name for this package.
    fn extract_version(&self, filename: &str) -> Option<String> {
        let stem = filename.strip_suffix(".tgz")?;
        // Try the longer prefix first so that for an unscoped package
        // (where `self.raw == self.basename`) we still match.
        let rest = stem.strip_prefix(&self.raw).or_else(|| stem.strip_prefix(&self.basename))?;
        let version = rest.strip_prefix('-')?;
        is_safe_segment(version).then(|| version.to_string())
