/// * the matching `time[v]` entries are removed.
/// * `dist-tags` entries whose target version was removed are dropped,
///   so no tag resolves to a version that's no longer present.
fn filter_vulnerable_versions(doc: &mut Value, osv: &crate::resolver::OsvIndex, package: &str) {
    let Some(obj) = doc.as_object_mut() else { return };
    let Some(versions) = obj.get("versions").and_then(Value::as_object) else { return };
    let removed: std::collections::HashSet<String> = versions
        .iter()
        .filter(|(key, entry)| !is_eligible_version(key, entry) || osv.is_vulnerable(package, key))
        .map(|(key, _)| key.clone())
        .collect();
    if removed.is_empty() {
        return;
    }
    if let Some(versions) = obj.get_mut("versions").and_then(Value::as_object_mut) {
        versions.retain(|key, _| !removed.contains(key));
    }
    if let Some(time) = obj.get_mut("time").and_then(Value::as_object_mut) {
        time.retain(|key, _| !removed.contains(key));
    }
    if let Some(tags) = obj.get_mut("dist-tags").and_then(Value::as_object_mut) {
        tags.retain(|_, target| target.as_str().is_none_or(|v| !removed.contains(v)));
    }
}

/// A version entry is eligible to be served only when its key is a
/// valid semver string and matches the entry's own `version` field.
/// A non-semver key can't be OSV-checked, and an identity mismatch
/// means the entry can't be trusted to be what its key claims.
fn is_eligible_version(key: &str, entry: &Value) -> bool {
    node_semver::Version::parse(key).is_ok()
        && entry.get("version").and_then(Value::as_str) == Some(key)
}

